use super::{HistoryCompletion, HistoryState};
use crate::value::Subscription;
use std::{
    cell::{Cell, RefCell},
    rc::Rc,
};

/// One host history entry. `None` represents an unrelated/unmanaged entry.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct HistoryEntry {
    /// Application history state, if this is a managed entry.
    pub state: Option<HistoryState>,
    /// Complete URL path and query generated by the controller.
    pub url: String,
}

/// Host operations required by the independent synchronization core.
///
/// `push` and `replace` must not generate pop notifications. `go` emits the
/// target pop notification before completion and calls completion exactly once;
/// completion may be deferred until the host has committed its movement.
/// A host must report impossible movement as an error rather than silently
/// dropping completion. Subscriptions cancel on drop and may coexist.
pub trait HistoryBackend {
    /// Current entry, or None before any entry exists.
    fn current(&self) -> Option<HistoryEntry>;
    /// Replaces the current entry (creates the initial entry when absent).
    fn replace(&self, entry: HistoryEntry) -> Result<(), super::HistoryError>;
    /// Appends an entry and discards the forward branch.
    fn push(&self, entry: HistoryEntry) -> Result<(), super::HistoryError>;
    /// Moves through existing entries and completes after the pop notification.
    fn go(&self, delta: isize, completion: HistoryCompletion);
    /// Registers notifications for host Back/Forward movement.
    fn subscribe(&self, observer: Rc<dyn Fn(Option<HistoryState>)>) -> Subscription;
}

struct Listener {
    callback: Rc<dyn Fn(Option<HistoryState>)>,
    active: Cell<bool>,
}
#[derive(Default)]
struct Memory {
    entries: Vec<HistoryEntry>,
    position: usize,
}

/// Single-threaded deterministic backend for tests and non-browser hosts.
#[derive(Clone, Default)]
pub struct MemoryHistoryBackend {
    memory: Rc<RefCell<Memory>>,
    listeners: Rc<RefCell<Vec<Rc<Listener>>>>,
}
impl MemoryHistoryBackend {
    /// Creates a host with no entries.
    pub fn new() -> Self {
        Self::default()
    }
    /// Creates an existing host history. The position must be in range.
    pub fn with_entries(
        entries: Vec<HistoryEntry>,
        position: usize,
    ) -> Result<Self, super::HistoryError> {
        if position >= entries.len() {
            return Err(super::HistoryError::Backend(
                "invalid history position".into(),
            ));
        }
        Ok(Self {
            memory: Rc::new(RefCell::new(Memory { entries, position })),
            listeners: Rc::default(),
        })
    }
    /// Snapshots all entries, including the retained forward branch.
    pub fn entries(&self) -> Vec<HistoryEntry> {
        self.memory.borrow().entries.clone()
    }
    /// Current absolute in-memory index.
    pub fn position(&self) -> usize {
        self.memory.borrow().position
    }
    /// Number of active host listeners.
    pub fn listener_count(&self) -> usize {
        self.listeners.borrow().len()
    }
}
impl HistoryBackend for MemoryHistoryBackend {
    fn current(&self) -> Option<HistoryEntry> {
        let memory = self.memory.borrow();
        memory.entries.get(memory.position).cloned()
    }
    fn replace(&self, entry: HistoryEntry) -> Result<(), super::HistoryError> {
        let mut memory = self.memory.borrow_mut();
        let position = memory.position;
        if memory.entries.is_empty() {
            memory.entries.push(entry);
        } else {
            memory.entries[position] = entry;
        }
        Ok(())
    }
    fn push(&self, entry: HistoryEntry) -> Result<(), super::HistoryError> {
        let mut memory = self.memory.borrow_mut();
        let next = memory.position + usize::from(!memory.entries.is_empty());
        memory.entries.truncate(next);
        memory.entries.push(entry);
        memory.position = next;
        Ok(())
    }
    fn go(&self, delta: isize, completion: HistoryCompletion) {
        let state = {
            let mut memory = self.memory.borrow_mut();
            let Some(target) = memory
                .position
                .checked_add_signed(delta)
                .filter(|target| *target < memory.entries.len())
            else {
                drop(memory);
                completion(Err(super::HistoryError::Backend(
                    "history movement out of bounds".into(),
                )));
                return;
            };
            memory.position = target;
            memory.entries[target].state.clone()
        };
        let listeners = self.listeners.borrow().clone();
        for listener in listeners {
            if listener.active.get() {
                (listener.callback)(state.clone());
            }
        }
        completion(Ok(()));
    }
    fn subscribe(&self, observer: Rc<dyn Fn(Option<HistoryState>)>) -> Subscription {
        let listener = Rc::new(Listener {
            callback: observer,
            active: Cell::new(true),
        });
        self.listeners.borrow_mut().push(listener.clone());
        let listeners = Rc::downgrade(&self.listeners);
        Subscription::from_cancel(move || {
            listener.active.set(false);
            if let Some(listeners) = listeners.upgrade() {
                let removed = {
                    let mut listeners = listeners.borrow_mut();
                    listeners
                        .iter()
                        .position(|entry| Rc::ptr_eq(entry, &listener))
                        .map(|i| listeners.remove(i))
                };
                drop(removed);
            }
        })
    }
}
